import{_ as r,C as n,o as s,c,a3 as l,E as d,w as i,j as t,a}from"./chunks/framework.CCylkYel.js";const h="/screens/projects/projects_menu.png",p="/screens/projects/project_settings_menu.png",g="/screens/settings/global_channel_menu.png",u="/screens/settings/encoder_button_menu.png",v=JSON.parse('{"title":"Project","description":"","frontmatter":{},"headers":[],"relativePath":"projects/index.md","filePath":"projects/index.md"}'),m={name:"projects/index.md"};function b(j,e,f,P,k,S){const o=n("ManualRelated");return s(),c("div",null,[e[1]||(e[1]=l('<h1 id="project" tabindex="-1">Project <a class="header-anchor" href="#project" aria-label="Permalink to &quot;Project&quot;">​</a></h1><p>A <strong>project</strong> is a complete saved setup: all 32 knobs, macros, up to eight racks, LFOs, snapshots, plus the clock, default MIDI channel, and encoder-button shortcut that make that set work.</p><h2 id="project-menu" tabindex="-1">Project menu <a class="header-anchor" href="#project-menu" aria-label="Permalink to &quot;Project menu&quot;">​</a></h2><p><img src="'+h+'" alt="Project menu" class="screen"></p><p>Rows that open another screen show a <strong>three-line list</strong> icon on the right; <strong>Save Project</strong> and <strong>Rename Project</strong> show a <strong>ring and dot</strong> icon because Select runs the action immediately.</p><table tabindex="0"><thead><tr><th>Action</th><th>What it does</th></tr></thead><tbody><tr><td><a href="#project-settings">Project Settings</a></td><td>Clock, default MIDI channel, encoder-button shortcut</td></tr><tr><td><a href="./list">Library</a></td><td>Browse, load, create, rename, save as, or delete projects</td></tr><tr><td>Save Project</td><td>Save the active project (shown when there are unsaved changes)</td></tr><tr><td>Rename Project</td><td>Rename the <strong>active</strong> project</td></tr></tbody></table><p>To update every out-of-date project after a firmware change, use <strong><a href="./../settings/#migrate-all-projects">Settings → Migrate All Projects</a></strong>.</p><h2 id="project-settings" tabindex="-1">Project Settings <a class="header-anchor" href="#project-settings" aria-label="Permalink to &quot;Project Settings&quot;">​</a></h2><p><img src="'+p+'" alt="Project Settings" class="screen"></p><p>These settings belong to the <strong>open project</strong>. Changing them marks the project unsaved; <strong>Save Project</strong> writes them. Loading another project applies that project&#39;s values.</p><p>New <strong>Empty</strong> and <strong>DAW Defaults</strong> projects start at Internal clock, <strong>120 BPM</strong>, MIDI channel <strong>1</strong>, and encoder = Clock Start/Stop. Projects you already have keep the clock, channel, and encoder shortcut that were on the S32 until you change them.</p><p>Loading or switching a project applies clock source and BPM and <strong>stops</strong> transport. Play does not start by itself.</p><h3 id="clock-settings" tabindex="-1">Clock Settings <a class="header-anchor" href="#clock-settings" aria-label="Permalink to &quot;Clock Settings&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Meaning</th></tr></thead><tbody><tr><td>Source</td><td>Internal, External, or Auto MIDI clock</td></tr><tr><td>BPM</td><td>Tempo when internal (20–300); also editable from Perform → edit mode → BPM or <a href="./../perform/tap-tempo">tap tempo</a></td></tr><tr><td>Transport</td><td>Running / Stopped (internal only). Live only — not saved with the project</td></tr></tbody></table><h3 id="channel" tabindex="-1">Channel <a class="header-anchor" href="#channel" aria-label="Permalink to &quot;Channel&quot;">​</a></h3><p>Default MIDI channel for macros and devices that use “global” channel.</p><p><img src="'+g+'" alt="Channel" class="screen"></p><p>Dot marks the active channel.</p><h3 id="encoder-button" tabindex="-1">Encoder Button <a class="header-anchor" href="#encoder-button" aria-label="Permalink to &quot;Encoder Button&quot;">​</a></h3><p>Choose what a standalone encoder press does from Perform.</p><p><img src="'+u+'" alt="Encoder Button" class="screen"></p><table tabindex="0"><thead><tr><th>Option</th><th>Action</th></tr></thead><tbody><tr><td>Clock Start/Stop</td><td>Toggle transport</td></tr><tr><td>Racks Shortcut</td><td>Jump to racks</td></tr><tr><td>LFOs Shortcut</td><td>Jump to S32 LFO grid</td></tr></tbody></table><h2 id="manual-save" tabindex="-1">Manual save <a class="header-anchor" href="#manual-save" aria-label="Permalink to &quot;Manual save&quot;">​</a></h2><p>Most edits — macros, racks, LFO wiring, device parameters, clock, channel, encoder — are kept in memory until you <strong>Save Project</strong>. Use <strong>Save Project</strong> before power-off if you want those changes back next time.</p><p>Switching to another project while you still have unsaved edits may show a prompt — save, discard, or cancel.</p><h2 id="at-a-glance" tabindex="-1">At a glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to &quot;At a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Racks per project</td><td>Up to <strong>8</strong></td></tr><tr><td>Project name length</td><td>Up to <strong>15</strong> characters</td></tr></tbody></table><p>You can store as many projects as your storage allows. Open <strong>Settings → Storage Info</strong> to see how much space is left. If save fails, see <a href="./../getting-started/troubleshooting">Troubleshooting</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li><strong>Save Project</strong> — structure, mapping, or Project Settings changed and you want it after power cycle.</li><li><strong>Snapshots</strong> — quick scene recall within one project (see <a href="./../snapshots/">Snapshots</a> — full guide coming soon).</li></ul></div>',29)),d(o,null,{default:i(()=>[...e[0]||(e[0]=[t("ul",null,[t("li",null,[t("a",{href:"./list"},"Library"),a(" — Create, load, rename, save as, delete")]),t("li",null,[t("a",{href:"./../concepts/projects-and-snapshots"},"Projects & snapshots concept"),a(" — What projects store")]),t("li",null,[t("a",{href:"./../settings/"},"Settings"),a(" — Note names, firmware, migrate all projects")]),t("li",null,[t("a",{href:"./../getting-started/troubleshooting"},"Troubleshooting"),a(" — Save and storage messages")])],-1)])]),_:1})])}const w=r(m,[["render",b]]);export{v as __pageData,w as default};
